VIDEO = {'footer': 'Linux Hardening Checker  ·  Security Basics  ·  Java', 'poster': {'headline': [('LINUX', 'text'), ('HARDENING CHECKER', 'accent')], 'taglines': [('Most host compromises begin with a setting that nobody looked at', 'gold')], 'before': {'code': '/tmp/.hidden-shell 4755', 'note': 'set-user-id, not allowed', 'tag': 'BEFORE'}, 'after': {'code': '4755 - 4000 = 0755', 'note': 'the fix a machine makes', 'tag': 'AFTER'}}, 'highlight': {'console_green': ['AFTER THE FIX', 'AFTER THE DECISIONS', 'THE HARDENED IMAGE'], 'console_rose': ['BEFORE THE FIX', 'BEFORE THE DECISIONS', 'THE REPORT', 'THE SCAN IN THE BUILD'], 'console_amber': ['HOW A MODE', 'HOW EACH NEW MODE', 'HOW THE ACCOUNT', 'HOW THE PORT', 'THE COUNT', 'A LATER CHANGE'], 'console_cyan': ['THE BUILD RULE']}}
